func refitRansacSamples(count: Int) -> [[Int]]? {
    guard (5...50).contains(count) else { return nil }
    let start = (count - 5) * 400
    return (0..<100).map { row in
        (0..<4).map { Int(refitSamples[start + row * 4 + $0]) }
    }
}
